head.b:skin:

/*
-----------------------------------------------
Blogger Template Style
Name:   BCorporate v3
Designer Url - http://www.favoritebtemplates.com
----------------------------------------------- */
html, body, div, span, applet, object, iframe, h1, h2, h3, h4, h5, h6, p, blockquote, pre, a, abbr, acronym, address, big, cite, code, del, dfn, em, img, ins, kbd, q, s, samp, small, strike, strong, sub, sup, tt, var, b, u, i, center, dl, dt, dd, ol, ul, li, fieldset, form, label, legend, table, caption, tbody, tfoot, thead, tr, th, td, article, aside, canvas, details, embed, figure, figcaption, footer, header, hgroup, menu, nav, output, ruby, section, summary, time, mark, audio, video {
border: 0;
padding:0;
font-size: 100%;
font: inherit;
vertical-align: baseline;
}
article, aside, details, figcaption, figure, footer, header, hgroup, menu, nav, section { display: block }
ol, ul { list-style: none }
blockquote, q { quotes: none }
blockquote:before, q:before {
content: '';
content: none;
}
article, aside, details, figcaption, figure, footer, header, hgroup, menu, nav, section { display: block }
.picfooter ol, .picfooter ul { list-style: none }
blockquote, q { quotes: none }
blockquote:before, q:before {
content: '';
content: none;
}
table {
border-collapse: collapse;
border-spacing: 0;
}
:focus { outline: 0 }
a:link { -webkit-tap-highlight-color: #f9e516 }
video, object, embed {
max-width: 100%;
height: auto!important;
}
iframe { max-width: 99% }
blockquote {
width: 93%;
font-style: italic;
font-weight: normal;
font-family: Georgia,Serif;
font-size: 13px;
padding: 15px 10px 20px 27px;
position: relative;
margin-top: 25px;
margin-bottom: 10px;
background: #f0f0f0;
text-align: center;
}
blockquote:before {
position: absolute;
content: '"';
font-size: 40px;
width: 50px;
left: -5px;
font-family: arial;
}
blockquote p { margin-bottom: 10px }
strong, b { font-weight: bold }
em, i, cite {
font-style: italic;
font-family: georgia;
}
small { font-size: 100% }
figure { margin: 10px 0 }
code, pre {
font-family: monospace,consolas,sans-serif;
font-weight: normal;
font-style: normal;
}
pre {
margin: 5px 0 20px 0;
line-height: 1.3em;
padding: 8px 10px;
overflow: auto;
}
code {
padding: 0 8px;
line-height: 1.5;
}
mark {
padding: 1px 6px;
margin: 0 2px;
color: black;
background: #FFD700;
}
address { margin: 10px 0 }
.item-thumbnail img{
max-width: 9999px
}
.widget,.section {
padding:0;
margin:0
}
.item-thumbnail  {
overflow: hidden;
display: block;
}
.item .widget  {
overflow: hidden;
display: block;
}
.Attribution {
display: none
}
.navbar, .navbar .widget {display: none! important}

/* Layouts
=====================================*/
body#layout{text-align:left;}
body#layout .container,
body#layout .footer-widgets,
body#layout #header-wrapper,
body#layout #big-wrapper,
body#layout #outer-wrapper{width:865px;padding:0;margin:0;}
body#layout #main-wrapper{width:510px;}
body#layout #box {overflow:visible;float:left;width:31%;}
body#layout #box1{overflow:visible;float:right;width:31%;}
body#layout #box3{overflow:visible;float:left;width:31%;}
body#layout #box6{overflow:visible;float:left;width:64%;}
body#layout #box4{overflow:visible;float:right;width:31%;}
body#layout div.section {padding: 7px;position: relative;margin: 0 0 20px;}
body#layout .section h4 {font-size: 13px;font-weight: 400;font-family: roboto;text-transform: uppercase;margin:0;padding:0;}
body#layout .widget-content {padding: 6px;}
/* Related-Posts h2
=====================================*/
#related-posts h2,.block-head h2,.comments h1,
.inter .widget>h2{
z-index:2;
position:relative;
background-color:#ffcc00 !important;
padding:0;
height:32px;
}
#related-posts h2:after,.block-head h2:after,.comments h1:after,
.inter .widget>h2:after{
position:absolute;
content:" ";display:block;
height:1px;
width:100%;
background-color:#fff;
left:0;
top:50%;
z-index:1;
margin-top:-1px;
}
#related-posts h2 span,.block-head h2 span,.comments h4 span>h2 span,
.inter .widget>h2 span{
z-index:2;
background:#587792;
font-size:18px;
font-family:'Oswald',serif,sans-serif;
padding:2px 7px 2px 7px;
text-transform:uppercase;
position:absolute;
top:0;
line-height:28px;
left:0;
color:#fff;
display:inline-block;
height:28px;
}
#related-posts h2 span:after,.block-head h2 span:after,.comments h1 span:after>h2 span:after,
.inter .widget>h2 span:after{
left:100%;
top:50%;
border:solid transparent;
content:" ";
height:0;
width:0;
position:absolute;
pointer-events:none;
border-color:rgba(205,33,34,0);
border-left-color:#1abc9c;
border-width:16px;
margin-top:-16px;
}
.widget,.section {
padding:0;
margin:0
}
/* Body
=====================================*/
body, .body-fauxcolumn-outer {
background: #939ead;
margin:0;
color:#777;
}
a {
color:#222;
text-decoration:none;
}
a:link {
color:#222;
text-decoration:none;
}
a:hover {
color:#000;
text-decoration:none;
}
/* Header
=====================================*/
#header-wrapper {
width:1080px;
height:100px;
background-color: #fff;
padding:17px 0;
margin:0 auto;
}
#header-inner {
background-position: center;
margin-left: auto;
margin-right: auto;
}
#header {
margin: 5px;
float:left;
width:400px;
text-align:left;
}
#header2 {
float:right;
width:350px;
padding:28px 30px 12px 0;
text-align:left;
}
#header h1 {
margin:5px 5px 0;
padding:5px 20px 5px 18px;
text-transform:none;
font-family: 'Mr Dafoe', cursive;
font-size: 52px;
color: #222;
font-weight:300;
}
#header a {
color:#222;
text-decoration:none;
}
#header a:hover {
color:#000;
}
#header .description {
margin:-10px 0 0 23px;
padding:0;
max-width:400px;
text-transform:none;
line-height: .4em;
font:normal 13px Oswald;
color: #222;
}
#header img {
margin-left: auto;
margin-right: auto;
}
/* Outer Wrapper
=====================================*/
#big-wrapper{
width:1080px;
margin:0 auto;
padding:0;
box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.9); 
-moz-box-shadow:0px 0px 10px rgba(0, 0, 0, 0.9); 
-webkit-box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.9);
}
#outer-wrapper {
width: 1040px;
background:#fff;
margin:0 auto;
padding:5px 20px 0 20px;
text-align:left;
font:normal 14px Arial;
}
#main-wrapper {
width: 720px;
float: left;
word-wrap: break-word;
overflow: hidden;
}
#sidebar-wrapper {
width: 300px;
float: right;
word-wrap: break-word;
}
/* Posts
=====================================*/
h2.date-header {
display:none;
}
.post {
margin:0 0 20px 0;
font-size:15px;
font-family:Open Sans;
color:#000000;
}
.post h2 {
margin:10px 0 10px 0;
padding:0 0 4px;
font-family: 'Oswald', cursive;
font-weight:300;
font-size:39px;
line-height:1.1em;
color:#000000;
}
.post h2 a, .post h2 a:visited, .post h2 strong {
display:block;
text-decoration:none;
font-weight:300;
}
.post-body blockquote {
line-height:1.3em;
}
.post img, table.tr-caption-container {
margin: 0 0 20px;
}
.tr-caption-container img {
border: none;
padding: 0;
}
.post-meta{ 
padding-bottom:9px; 
padding-top: 9px; 
font-family: 'Kreon', Arial, sans-serif; 
font-weight: lighter; 
font-size: 16px; 
color: #000000; 
border-top: 1px solid #ddd; 
border-bottom: 1px solid #ddd; 
margin-bottom: 20px; 
}
.post-meta a{ 
color: #000000; 
text-decoration: none; 
}
.post-meta a:hover { 
color: #111; 
}
/* Page Navigation
=====================================*/
.showpageOf {
display: none;
}
.showpagePoint {
padding: 8px 14px;
background: #222;
border:1px solid #222;
float: left;
color: #fff;
margin-right:1px;
font-size: 14px;
font-weight: bold;
}
.showpage a, .showpageNum a {
padding: 8px 14px;
background: #fff;
border:1px solid #b9b9b9;
float: left;
color: #666;
margin-right:1px;
font-size: 14px;
font-weight: bold;
text-decoration: none;
}
.showpage a:hover {
background: #1f1f1f;
color:#fff
}
.showpageNum a:hover {
background: #222;
border:1px solid #222;
color:#fff
}
.showpageArea {
text-align:center;
}
/* Comments
=====================================*/
#comments{
font-size:13px;
background: #efefef;
margin:0;
padding:15px;
}
#comments h4{display:inline;padding:10px;line-height:40px}
#comments h4,.comments .comment-header,.comments .comment-thread.inline-thread .comment{position:relative}
#comments h4,.comments .continue a{background:#333}
#comments h4,.comments .user a,.comments .continue a{font-size:16px}
#comments h4,.comments .continue a{font-weight:normal;color:#fff}
#comments h4:after{content:"";position:absolute;bottom:-10px;left:10px;border-top:10px solid #333;border-right:20px solid transparent;width:0;height:0;line-height:0}
#comments .avatar-image-container img{border:0}
.comment-thread{color:#111}
.comment-thread a{color:#777}
.comment-thread ol{margin:0 0 20px}
.comment-thread .comment-content a,.comments .user a,.comments .comment-thread.inline-thread .user a{color:#E74C3C}
.comments .avatar-image-container,.comments .avatar-image-container img{
width:48px;
max-width:48px;
height:48px;
max-height:48px
}
.comments .comment-block,.comments .comments-content .comment-replies,.comments .comment-replybox-single{
margin-left:60px
}
.comments .comment-block,.comments .comment-thread.inline-thread .comment{
border:1px solid #ddd;
background:#fff;
padding:10px
}
.comments .comments-content .comment{
margin:15px 0 0;
padding:0;
width:100%;
line-height:1em
}
.comments .comments-content .icon.blog-author{
position:absolute;
top:-12px;
right:-12px;
margin:0;
background-image: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhdqxaVCz7lM3WT6Lp_KH5dqFCpHJ3KyBRfm9ZCUWjDkRKVUTj_xPIeic5VEDWo5SxCNwgoESmDX2nawFU62P_gUUAHGTdBLsOndvM3CVdi8ySAp2syDB2NSciyaBbV0YkhDtMzEpUFVBaS/s1600/author.png);
width:36px;
height:36px
}
.comments .comments-content .inline-thread{padding:0 0 0 20px}
.comments .comments-content .comment-replies{margin-top:0}
.comments .comment-content{padding:5px 0;line-height:1.4em}
.comments .comment-thread.inline-thread{
border-left:1px solid #ddd;
background:transparent
}
.comments .comment-thread.inline-thread .comment{width:auto}
.comments .comment-thread.inline-thread .comment:after{
content:"";
position:absolute;
top:10px;
left:-20px;
border-top:1px solid #ddd;
width:10px;height:0px
}
.comments .comment-thread.inline-thread .comment .comment-block{
border:0;
background:transparent;
padding:0
}
.comments .comment-thread.inline-thread .comment-block{margin-left:48px}
.comments .comment-thread.inline-thread .user a{font-size:13px}
.comments .comment-thread.inline-thread .avatar-image-container,.comments .comment-thread.inline-thread .avatar-image-container img{
width:36px;
max-width:36px;
height:36px;
max-height:36px
}
.comments .continue{border-top:0;width:100%}
.comments .continue a{padding:10px 0;text-align:center}
.comment .continue{display:none}
#comment-editor{width:103%!important}
.comment-form{width:100%;max-width:100%}
.comments .comments-content .loadmore,.comments .comments-content {margin:0}
/* Blog Pager
=====================================*/
#blog-pager-newer-link {
float: left;
}
#blog-pager-older-link {
float: right;
}
#blog-pager {
text-align: center;
padding-top:20px;
margin-bottom:0;
}
.feed-links {
display:none;
}
/* Sidebar
=====================================*/
.sidebar {
line-height: 1.3em;
}
.sidebar h2 {
border-bottom:3px solid #777;
padding:12px 0 3px 0;
font-family: Oswald, sans serif;
text-transform: uppercase;
text-align:left;
font-weight: 400;
font-size: 22px;
line-height:26px;
color:#000000;
}
.sidebar ul {
padding: 0;
margin: 0;
list-style: none;
}
.sidebar li {
display:block;
}
.sidebar .widget, .main .widget {
margin:0 0 1.5em;
padding:0 0 1.5em;
}
.main .Blog {
border-bottom-width: 0;
}
/* Labels
=====================================*/
.cloud-label-widget-content {
float:left;
margin-bottom:8px;
padding:10px 0px 0px 0px;
border:0;
}
.cloud-label-widget-content li, .cloud-label-widget-content a {
background:#f2f2f2;
border:2px solid #eaeaea;
color:#ffffff;
float:left;
font-family: Lato, sans-serif;
font-size:13px !important;
margin:4px 4px 0 0;
padding:9px 9px;
text-decoration:none;
-webkit-transition:all 0.4s ease 0s;
-moz-transition:all 0.4s ease 0s;
-ms-transition:all 0.4s ease 0s;
-o-transition:all 0.4s ease 0s;
transition:all 0.4s ease 0s;
}
.cloud-label-widget-content a:hover {
background: #333;
border:2px solid #444;
color:#fff;
}
.footer-widgets .cloud-label-widget-content li, .footer-widgets .cloud-label-widget-content a{
background:none;
border:1px solid #777;
color:#777;
float:left;
font-family: Lato, sans-serif;
font-size:13px !important;
margin:4px 4px 0 0;
padding:9px 9px;
text-decoration:none;
-webkit-transition:all 0.4s ease 0s;
-moz-transition:all 0.4s ease 0s;
-ms-transition:all 0.4s ease 0s;
-o-transition:all 0.4s ease 0s;
transition:all 0.4s ease 0s;
}
.status-msg-wrap{
display:none;
}
/* Archive
=====================================*/
.BlogArchive #ArchiveList ul li{
list-style: none;
display: block;
padding: 5px 0 5px 15px;
text-decoration: none;
text-shadow: -1px -1px 0 #EEEEEE;
}
#BlogArchive1_ArchiveMenu {
width: 100%;
border: 2px solid #eaeaea;
background: #f2f2f2;
padding: 10px;
}
/* Footer
=====================================*/
/* Footer */
.container {
    background-color: #333;
    width: 100%;
    max-width: 1080px;
    overflow: hidden;
    margin: 0 auto;
}

footer p {
    color: #aaa;
}

.footer-widgets {
    overflow: hidden;
    padding: 20px 2.8% 10px 3.1%;
    width: 94.6%;
    margin: 0;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
}

.footer-widgets .f-widget {
    flex: 1 1 20%;
    position: relative;
    color: #aaa;
    font-family: Lato, sans-serif;
    font-size: 13px;
    margin-bottom: 30px;
    padding-bottom: 20px;
}

.footer-widgets .f-widget.last {
    margin-right: 0;
    border: none;
    overflow: hidden;
}

.footer-widgets .f-widget h2 {
    background: none;
    color: #ccc;
    border-bottom: 3px solid #999;
    padding: 5px 0;
    font-size: 20px;
    font-family: Oswald;
    font-weight: 400;
    margin-bottom: 16px;
}

.footer-widgets ul li a {
    color: #aaa;
    font-family: Lato, sans-serif;
    font-size: 15px;
    text-decoration: none;
}

.footer-widgets ul li a:visited {
    color: #aaa;
}

#credit {
    width: 100%;
    max-width: 1080px;
    background: #222;
    border-top: 1px solid #444;
    z-index: 9999;
    font-family: Lato, sans-serif;
    font-size: 13px;
    color: #ddd;
    overflow: hidden;
    margin: 0 auto;
    clear: both;
    padding: 10px 0;
    line-height: 20px;
}

#credit .credit-content {
    width: 100%;
    text-align: center;
    padding: 0;
    margin: 0 auto;
}

#credit a {
    color: #fff;
    text-decoration: none;
}

#credit a:hover {
    color: #fc0;
    text-decoration: none;
}

/* Responsive Styles for Footer */
@media screen and (max-width: 1024px) {
    .footer-widgets .f-widget {
        flex: 1 1 45%;
    }
}

@media screen and (max-width: 768px) {
    .footer-widgets .f-widget {
        flex: 1 1 100%;
    }

    #credit .credit-content {
        float: none;
        width: 100%;
    }
}

@media screen and (max-width: 600px) {
    .footer-widgets {
        flex-direction: column;
        align-items: center;
    }

    #credit {
        text-align: center;
    }
}

/* Social Network
=====================================*/
.social-icons{
text-align:center;
}
.social-icons a{
position:relative;
margin:0; 
opacity:.7;
}
.social-icons a:hover{ opacity:1;}
.social-icons.icon_24 img{
width:24px; 
height:24px;
}
.social-icons.icon_16 img{
width:16px; 
height:16px;
}
.social-icons.icon_flat{
float:left; 
margin:4px 0 0 0;
}
.social-icons.icon_flat a{
background:url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEha8aT11BBCMhkCPepGtrnV5svGNZYMB_z25PuphrBXhHPPa67-ICTo4dUuRuwTZLdEn15Dp3hX-yg54KSTJcVZDs4xH0P0pZzZ_A5u-TPOjxPkt_QwVj3_NMxOkcpkDHjNRl5G3lvJSy03/s1600/social-icons.png) no-repeat top left; 
width: 20px;
height: 20px; 
opacity:.3;
}
.social-icons.icon_flat a:hover{ opacity:.6;}
.icon_flat a.google-tieicon{background-position:-38px 1px;}
.icon_flat a.facebook-tieicon{background-position:left 0;}
.icon_flat a.twitter-tieicon{background-position:-76px 1px;}
.icon_flat a.youtube-tieicon{background-position:-38px -82px;}
.icon_flat a.dribbble-tieicon{background-position:-121px -82px;}
.icon_flat a.rss-tieicon{background-position:left -123px;}
.icon_flat a.pinterest-tieicon{background-position:-76px -123px;}
.icon_flat a.instagram-tieicon{background-position:left -209px;}
a.ttip, a.tooldown{display:inline-block;}
/* Contact Form
=====================================*/
.contact-form-button{
border-radius:3x !important;
width:95%;
margin-top:10px;
}
.contact-form-name,.contact-form-email,.contact-form-email-message{
max-width:95%;
margin-bottom:5px;
color:#333;
}
.contact-form-email:hover,.contact-form-name:hover,.contact-form-email-message:hover{
box-shadow:none
}
input:focus,.contact-form-email-message{
box-shadow:none
}
.contact-form-email-message{
border:none !important;
border-top:0px;
border:0px
}
.contact-form-email, .contact-form-name{
background:#444;
color:#999;
border:1px solid #555!important;
padding:15px;
}
.contact-form-name, .contact-form-email, .contact-form-email-message{
background:#444;
border:1px solid #555!important;
color:#999;
padding:15px;
}
.contact-form-button-submit{
background:#7daddb;
width:40%;
float:left;
background-color:#000000!important;
border:none !important;
box-shadow:none !important;
border-radius:none !important
}
.contact-form-button-submit:hover{
background:#7daddb;
background-color:#7DADDC!important;
color:#7daddb!important;
}
/* Copyrights
=====================================*/
#credit{
width: 1080px;
background:#222;
border-top:1px solid #444;
z-index:9999;
font-family: Lato, sans-serif;
font-size:13px;
color: #ddd;
overflow:hidden;
margin:0 auto;
clear:both;
padding:10px 0;
line-height:20px;
}
#credit .left{
float:left;
text-align:left;
margin-left:30px;
margin-top:5px;
}
#credit .right{
float:right;
text-align:right;
margin-right:30px;
}
#credit a{
color:#fff;
text-decoration:none;
}
#credit a:hover{
color:#fc0;
text-decoration:none
}
/* Popular Posts
=====================================*/
#PopularPosts1 img {
float:left;
margin:0 5px 0 0;
}
.item-thumbnail img {
width: 60px;
height: 60px;
}
#PopularPosts1 .item-title {
font: 300 14px Lato, sans serif;
}
#PopularPosts1 dd {
border-bottom: 1px solid #000000;
padding: 8px 0 4px;
}
/* Dropdown Menu
=====================================*/
#menu{
background: #f2f2f2;
border-top:2px solid#eaeaea;
border-bottom:2px solid #eaeaea;
color: #000000;
height: 50px;
z-index:9;
width:1080px;
margin:0 auto;
}
#menu ul,#menu li{margin:0 auto;padding:0 0;list-style:none}
#menu ul{height:80px;width:1080px}
#menu li{float:left;display:inline;position:relative;font:bold 12px "Arial", sans-serif; text-transform:none;}
#menu a{display: block;
line-height: 50px;
padding: 0 30px;
text-decoration: none;
color: #000000;
border-right:1px solid #ddd;
}
#menu li a:hover{
color: #000000;
-webkit-transition-duration: 1.0s; /*Webkit: Animation duration*/
-moz-transition-duration: 1.0s; /*Mozilla Animation duration*/
-o-transition-duration: 1.0s; /*Opera Animation duration*/
}
li.home a{background:none;}
#menu input{display:none;margin:0 0;padding:0 0;width:65px;height:50px;opacity:0;cursor:pointer}
#menu label{font:bold 60px Oswald;display:none;width:60px;height:50px;line-height:36px;text-align:center}
#menu label span{font-size:16px;position:absolute;left:35px}
#menu ul.menus{
height: auto;
overflow: hidden;
width: 190px;
background: #ebebeb;
position: absolute;
z-index: 99;
display: none;
}
#menu ul.menus li{
display: block;
width: 100%;
font:bold 12px Arial;
text-transform: none;
text-shadow: none;
}
#menu ul.menus a{
color: #555;
line-height: 35px;
}
#menu li:hover ul.menus{display:block}
#menu ul.menus a:hover{
background: #f2f2f2;
color:#000000;
-webkit-transition: all .1s ease-in-out;
-moz-transition: all .1s ease-in-out;
-ms-transition: all .1s ease-in-out;
-o-transition: all .1s ease-in-out;
transition: all .1s ease-in-out;
}
@media screen and (max-width: 800px){
#menu{position:relative}
#menu ul{background:#ebebeb;position:absolute;top:100%;right:0;left:0;z-index:3;height:auto;display:none}
#menu ul.menus{width:100%;position:static;padding-left:20px}
#menu li{display:block;float:none;width:auto; font:normal 0.8em Arial;}
#menu input,#menu label{position:absolute;top:0;left:0;display:block}
#menu input{z-index:4}
#menu input:checked + label{color:black}
#menu input:checked ~ ul{display:block}
}
