/* Carousel
=====================================*/
#carousel {
width: 1040px; 
position: relative; 
margin: 0 auto;
height:240px;
margin-bottom:40px;
float:left;
}
#carousel .content {
position: relative;
left: 0px;
width: 1040px;
overflow:hidden;
}
.crosscol h1{
border-bottom:3px solid  #000000;
padding:12px 0 3px 0;
text-align:left;
font-family: Oswald;
font-size:28px;
text-transform: none;
color:  #000000;
line-height: 35px;
}
#carousel ul{
width:10000px;
position: relative;
overflow:hidden;
margin-top:0px;
}
#carousel ul li {
display: block; 
float: left; 
margin:0;
margin-right:10px;  
width: 340px; 
overflow: hidden;
height:200px;
}
#carousel .thumb{
height:128px;
width: 340px;
}
#carousel .thumb img{
width: 450px;
}
#carousel  #previous_button {
position: absolute;
bottom:30px;
left: 0;
width: 47px;
height: 47px;
cursor: pointer;
background: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjLRVeyG5ZtmDtVqoUhHYjAHdplg-jQCJ3e0C92l4rdaSO-M5jTkOCfKVUZxqn4pVnvlvtIDzvFwHMhBvhjUCwJxAblqMh64kZsNJLo4LmRFV7HpT-7ayyTUofaN0T949nBg4gMaBhC0Wbx/s1600/slider-arrows.png) no-repeat;
z-index:999;
}
#carousel #next_button {
position: absolute;
bottom:30px;
right:0;
width: 47px;
height: 47px;
cursor: pointer;
background: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjLRVeyG5ZtmDtVqoUhHYjAHdplg-jQCJ3e0C92l4rdaSO-M5jTkOCfKVUZxqn4pVnvlvtIDzvFwHMhBvhjUCwJxAblqMh64kZsNJLo4LmRFV7HpT-7ayyTUofaN0T949nBg4gMaBhC0Wbx/s1600/slider-arrows.png) no-repeat;
background-position:100% 0;
z-index:999;
}
#carousel #next_button:hover, #previous_button:hover { 
-ms-filter: "progid: DXImageTransform.Microsoft.Alpha(Opacity=80)"; 
filter: alpha(opacity=80); 
opacity: 0.8; 
transition: opacity .25s ease-in-out; 
-moz-transition: opacity .25s ease-in-out; 
-webkit-transition: opacity .25s ease-in-out; 
}
#carousel ul li a.slider_title{
background:#111;opacity:0.7;filter:alpha(opacity = 70);padding:3px 8px;overflow:hidden;
color:#fff;
float:left;
height:39px;
width:324px;
text-align:left;
font:200 15px Oswald, sans serif;
margin-top:27px;
}
#carousel ul li a.slider_title:hover{
color:#fc0;
}
