  #newsletter_wrapper {
    width: 360px;
  }
  .headline-wrapper, .headline {
    max-width: 400px;
  }
  .headline-left {
    max-width: 50%;
  }
  #menu, #menu ul {
    max-width: 400px;
  }
  #outer-wrapper {
    max-width: 360px;
  }
  #main-wrapper {
    width: 360px;
    max-width: 360px;
  }
  #thumb-wrapper {
    max-width: 360px;
    margin: 0 auto;
  }
  .container, #newsletter, .headline-wrapper, #about, .fp-slider {
    display: block;
    width: 100%;
  }
  #credit {
    max-width: 400px;
  }
}

@media screen and (max-width:384px) {
  #big-wrapper {
    width: 350px;
  }
  #header-wrapper {
    max-width: 350px;
    height: auto;
  }
  #header {
    max-width: 350px;
  }
  #header2 {
    display: none;
  }
  #header h1 {
    font-size: 30px;
  }
  #menu, #menu ul {
    max-width: 350px;
  }
  #outer-wrapper {
    max-width: 310px;
  }
  #main-wrapper {
    float: left;
    width: 310px;
    max-width: 310px;
    padding: 0;
    margin: 0;
  }
  #thumb-wrapper {
    max-width: 300px;
  }
  #box, #box1, #box3, #box4 {
    width: 300px;
  }
  .mastoras_wide {
    max-width: 300px;
  }
  .box6 {
    max-width: 300px;
    overflow: hidden;
    margin-left: -20px;
  }
  .container, #credit {
    max-width: 350px;
  }
  .footer-widgets h2 {
    font-size: 12px;
  }
}

